{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fremstiller vurderingen som et spørgsmål om, om den studerende 'stort set ikke kan påtage sig erhvervsarbejde i nævneværdigt omfang' og som en generel arbejdsevnevurdering. Det er ikke i frosne kilder og afviger fra rubrikken. Svaret nævner ikke den individuelle, lægefagligt dokumenterede samlede vurdering af aktuelle symptomer. Det nævner heller ikke behandling og effekt, restsymptomer eller bivirkninger, rimelig medvirken eller sygdommens varighed, gentagelser og tilbagefaldsrisiko. Det tilføjer desuden udelukkelser af økonomi, studietid og jobbenes studierelevans/geografi uden støtte i materialet."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de fire kritiske elementer er kun et svagt spor af 'funktionsnedsættelsens art og grad' med. Der mangler individuel samlet vurdering på lægefagligt grundlag, påvirkning af dagligt funktionsniveau, behandling/effekt/restsymptomer/medvirken samt varighed/gentagelser/tilbagefald."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet er, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden. Svaret fokuserer på erhvervsevne, arbejdsevnevurdering og negative afgrænsninger i stedet for de egentlige vurderingsmomenter. Det besvarer derfor ikke de væsentlige dele af spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver kilder, herunder vejledning nr. 10157 af 5. oktober 2026 og to afgørelser fra Ankenævnet. Nogle påstande er markeret 'uden kilde', men mange væsentlige udsagn er knyttet til identificerbare kilder."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De viste kilder er Retsinformation-vejledningen VEJ nr. 10157 af 05/10/2026 og ankenævnsafgørelser. Vejledningen er aktuel og autoritativ. Afgørelserne eksisterer som kilder, men er ældre afgørelser. Der er ikke grundlag for at underkende kildernes gyldighed."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Den fremlagte passage i afsnit 3.4.1.2 støtter ikke påstandene om, at sværhedsgraden handler om, at man 'stort set ikke kan' arbejde, eller at det er en generel arbejdsevnevurdering. Den støtter heller ikke, at økonomi, studietid, studierelevans og geografi er udelukket. Flere påstande er desuden markeret 'uden kilde'."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en tærskel ('stort set ikke ... i nævneværdigt omfang'), en regel om generel arbejdsevnevurdering og flere udelukkede hensyn (økonomi, studietid, studierelevans, geografi) uden støtte i de frosne kilder. Flere af tilføjelserne er selv markeret 'uden kilde'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Rubrikken kræver, at momenterne fremgår som eksempler i en individuel helhedsvurdering. Svaret gengiver ikke dette forbehold. Det erstatter momenterne med en snæver arbejdsevnetest og negative afgrænsninger fremstillet som faste."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt nogenlunde sammenhængende: art/grad, så konsekvenser for arbejdsevne, så en generel vurdering og en afsluttende sammenfatning. Konklusionen følger af de skridt, svaret selv opstiller, selv om skridtene er juridisk forkerte eller mangelfulde."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør vurderingen absolut: 'Der lægges derimod ikke vægt på ...' og 'indgår heller ikke'. Det er uden støtte. Samtidig er den ikke-udtømmende, eksempelvise karakter af momenterne ('f.eks.') ikke gengivet."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "no",
      "reason": "Svaret fremhæver ikke, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret. Det nævner heller ikke momenterne i vurderingen: hvad den studerende fejler, daglig funktion, behandling og effekt, restsymptomer/bivirkninger, rimelig medvirken eller varighed/gentagelser/tilbagefald. Det nævner kun 'art og grad' af en varig funktionsnedsættelse."
    }
  },
  "overall_notes": "Svaret er juridisk upræcist og ufuldstændigt. Det erstatter de lægefaglige momenter og helhedsvurderingen med en arbejdsevnetærskel og negative afgrænsninger uden støtte i de frosne kilder. Der er kildehenvisninger, men de understøtter ikke de væsentlige påstande. Svaret bærer selv forbeholdet 'Begrænset svar'."
}

